import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load watch mesh from GLB
  const glbData = ctx.glbLoader.load('/prism-mock/orrery/meshes/watch.glb');
  const watchMesh = glbData.scene.clone ? glbData.scene.clone() : glbData.scene;
  group.add(watchMesh);

  // Create plinth (cylindrical base)
  const plinthGeom = new THREE.CylinderGeometry(1.4, 1.4, 0.25, 32);
  const plinthMat = new THREE.MeshStandardMaterial({
    color: 0x14141a,
    roughness: 0.7,
    metalness: 0.3,
  });
  const plinth = new THREE.Mesh(plinthGeom, plinthMat);
  plinth.position.y = -1.1;
  group.add(plinth);

  // Contact shadow (radial beneath plinth)
  const shadowGeom = new THREE.CircleGeometry(1.6, 32);
  const shadowMat = new THREE.MeshBasicMaterial({
    color: 0x000000,
    opacity: 0.55,
    transparent: true,
    depthWrite: false,
  });
  const shadow = new THREE.Mesh(shadowGeom, shadowMat);
  shadow.position.set(0, -1.1225, 0.01);
  shadow.rotation.x = -Math.PI / 2;
  group.add(shadow);

  // Backdrop plane with gradient appearance
  const backdropGeom = new THREE.PlaneGeometry(7, 6);
  const backdropMat = new THREE.MeshBasicMaterial({
    color: 0x16161d,
  });
  const backdrop = new THREE.Mesh(backdropGeom, backdropMat);
  backdrop.position.z = -2.5;
  group.add(backdrop);

  // Lighting setup
  const keyLight = new THREE.DirectionalLight(0xffffff, 1.0);
  keyLight.position.set(1, 1.5, 1.5);
  keyLight.castShadow = false;
  group.add(keyLight);

  const fillLight = new THREE.DirectionalLight(0xffffff, 0.3);
  fillLight.position.set(-1, 0, 1);
  group.add(fillLight);

  const rimLight = new THREE.DirectionalLight(0xff2a38, 1.6);
  rimLight.position.set(-2, 0.5, 1);
  rimLight.intensity = 1.6;
  group.add(rimLight);

  // Text via fontAtlas
  const headlineText = ctx.fontAtlas.createText('Calibre NA-01', {
    fontFamily: 'Lora',
    fontSize: 68,
    fontWeight: 600,
    color: 0xe8ecf2,
    letterSpacing: -0.005,
  });
  headlineText.position.set(-1.7, -1.5, 0);
  group.add(headlineText);

  const bodyText = ctx.fontAtlas.createText('Machined in-house. 41 mm. Grade 5 titanium.', {
    fontFamily: 'JetBrains Mono',
    fontSize: 26,
    fontWeight: 400,
    color: 0xe8ecf2,
    letterSpacing: 0,
  });
  bodyText.position.set(-2.0, -1.75, 0);
  group.add(bodyText);

  const captionText = ctx.fontAtlas.createText('FROM 4200 USD / SHIPS IN 21 DAYS', {
    fontFamily: 'JetBrains Mono',
    fontSize: 18,
    fontWeight: 400,
    color: 0xff2a38,
    letterSpacing: 0.08,
  });
  captionText.position.set(-2.2, -2.0, 0);
  group.add(captionText);

  // Apply cinematic primitives
  ctx.primitives.orbit(group, { speed: 0.15, radius: 0.6 });

  // Hover interaction state
  let depthRotateTimeline = null;
  let settleTimeline = null;

  group.userData.handlers = {
    hover: (isEntering) => {
      if (isEntering) {
        if (settleTimeline) settleTimeline.kill();
        ctx.primitives['depth-rotate'](watchMesh, { 
          maxDeg: 6,
          duration: 0.3,
          easing: 'cubic-bezier(0.215,0.61,0.355,1)',
        });
      } else {
        if (depthRotateTimeline) depthRotateTimeline.kill();
        settleTimeline = gsap.to(watchMesh.rotation, {
          x: 0,
          y: 0,
          z: 0,
          duration: 0.9,
          ease: 'cubic-bezier(0.165,0.84,0.44,1)',
        });
      }
    }
  };

  // Cleanup
  group.userData.cleanup = () => {
    if (depthRotateTimeline) depthRotateTimeline.kill();
    if (settleTimeline) settleTimeline.kill();

    plinthGeom.dispose();
    plinthMat.dispose();
    shadowGeom.dispose();
    shadowMat.dispose();
    backdropGeom.dispose();
    backdropMat.dispose();
  };

  return group;
}
